static void testJpeg() {
    const std::vector<uint8_t> d(kJpeg, kJpeg + sizeof kJpeg);
    check(detectUiImage(d) == UiImageFormat::Jpeg, "JPEG detected");
    std::string err;
    auto img = decodeUiImage(d, &err);
    check(img && img->width == 16 && img->height == 16, "JPEG decoded");
    if (img) {
        pixel(*img, 3, 3, 255, 0, 64, 255, 24, "JPEG top-left");
        pixel(*img, 12, 3, 0, 0, 64, 255, 24, "JPEG top-right");
        pixel(*img, 3, 12, 255, 255, 64, 255, 24, "JPEG bottom-left");
        pixel(*img, 12, 12, 0, 255, 64, 255, 24, "JPEG bottom-right");
    }
    // An ALFA segment right after SOI sets the alpha: 256 pixels as two runs of 128
    // (0x81 = -127 repeats the next byte 128 times).
    std::vector<uint8_t> withAlpha(d.begin(), d.begin() + 2);
    for (uint8_t b : {0xFF, 0xE0, 0x00, 0x0A, 0x41, 0x4C, 0x46, 0x41, 0x81, 0x40, 0x81, 0xC0})
        withAlpha.push_back(b);
    withAlpha.insert(withAlpha.end(), d.begin() + 2, d.end());
    auto a = decodeUiImage(withAlpha);
    check(a.has_value(), "JPEG with ALFA decoded");
    if (a) {
        pixel(*a, 3, 3, 255, 0, 64, 0x40, 24, "ALFA first half");
        pixel(*a, 12, 12, 0, 255, 64, 0xC0, 24, "ALFA second half");
    }
}

int main() {
    testScript();
    testTga();
    testBmp();
    testJpeg();
    if (failures)
        std::fprintf(stderr, "%d failure(s)\n", failures);
    else
        std::printf("ui tests passed\n");
    return failures ? 1 : 0;
}
